def solution(storage, requests):
    from collections import deque

    n = len(storage)
    m = len(storage[0])

    grid = [[0] * (m + 2) for _ in range(n + 2)]
    for i in range(n):
        for j in range(m):
            if storage[i][j]:
                grid[i + 1][j + 1] = storage[i][j]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start_x, start_y, target):
        queue = deque([(start_x, start_y)])
        visited = set()
        visited.add((start_x, start_y))

        while queue:
            x, y = queue.popleft()

            if grid[x][y] == target:
                return True

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 < nx <= n and 0 < ny <= m and (nx, ny) not in visited and grid[nx][ny]:
                    visited.add((nx, ny))
                    queue.append((nx, ny))

        return False

    def crane_pick(target):
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if grid[i][j] == target:
                    grid[i][j] = ''
                    return True
        return False

    result = []

    for request in requests:
        if len(request) > 1:
            crane_pick(request)
        else:
            found = False
            for i in range(1, n + 1):
                for j in range(1, m + 1):
                    if grid[i][j] == request:
                        grid[i][j] = ''
                        found = True
                        break
                if found:
                    break
            if not found:
                for i in range(1, n + 1):
                    for j in range(1, m + 1):
                        if grid[i][j] == request:
                            grid[i][j] = ''
                            break
                    if found:
                        break

    count = sum(sum(row) for row in grid)
    result.append(count)

    return result

