def solution(edges):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    node_count = len(graph)

    # Find connected components using DFS
    visited = set()
    def dfs(node):
        if node in visited:
            return 0
        visited.add(node)
        size = 1
        for neighbor in graph[node]:
            size += dfs(neighbor)
        return size

    component_sizes = []
    for node in graph:
        if node not in visited:
            size = dfs(node)
            component_sizes.append(size)

    # Count the number of each type of graph based on their properties
    doughnut_count = 0
    stick_count = 0
    octagon_count = 0

    for size in component_sizes:
        if size > 1 and (size - 1) % 2 == 0:
            doughnut_count += 1
        elif size > 1 and (size - 1) % 2 != 0:
            stick_count += 1
        elif size > 1:
            octagon_count += 1

    return [node_count + 1] + [doughnut_count, stick_count, octagon_count]
